//! B-652: D-772, Turbulent Noise's cell and contrast match After Effects': Size 100 at Scale 100
//! draws Fractal Noise's 66.7-pixel cell (c = size / 1.5), and Contrast spreads the greys 0.64
//! times as far as before.
//!
//! Writes `verification/B-652_turbulent_size_contrast_table.md`. The fixtures' numbers are the
//! reference's (`tools/turbulent_noise_reference.py` and the three that follow it), regenerated by
//! D-772; the cell widths are counted here on Block noise of one octave, whose cells are flat.

mod effect_table;

use std::fs;

use effect_table::{both, repo, Table, MAIN};
use serde_json::{json, Value as J};

use anime_compositor::compose::render_frame;
use anime_compositor::diagnostics::FrameLog;
use anime_compositor::gpu::Gpu;
use anime_compositor::model::Id;
use anime_compositor::persist;
use anime_compositor::preview::PreviewQuality;

const WIDE: usize = 400;

/// A white 400 by 8 solid under one effect of `type_id` with `parameters`.
fn shot(type_id: &str, parameters: J) -> String {
    let t = |v: J| json!({"base": v, "keyframes": []});
    json!({
        "schema_version": 0, "project_id": "proj-b652",
        "color_settings": {"working_space": "linear-srgb", "alpha_mode": "premultiplied"},
        "assets": [],
        "compositions": [{
            "id": MAIN, "name": MAIN, "width": WIDE, "height": 8, "pixel_aspect_ratio": 1,
            "frame_rate": {"numerator": 24, "denominator": 1}, "start_frame": 0,
            "duration_frames": 1, "work_area": {"start_frame": 0, "end_frame_exclusive": 1},
            "layer_order": ["white"],
            "layers": [{
                "id": "white", "kind": "solid", "name": "white", "enabled": true, "locked": false,
                "in_frame": 0, "out_frame": 1,
                "solid": {"color": [1, 1, 1], "width": WIDE, "height": 8},
                "transform": {
                    "anchor": t(json!([200, 4])), "position": t(json!([200, 4])),
                    "scale": t(json!([100, 100])), "rotation": t(json!(0)), "opacity": t(json!(1))
                },
                "masks": [], "matte": null, "blend_mode": "normal",
                "effects": [{"instance_id": "f", "type_id": type_id, "enabled": true, "parameters": parameters}]
            }]
        }]
    })
    .to_string()
}

/// A noise of `type_id` with `p` over the settings both share as Turbulent Noise adds them;
/// a Fractal Noise also gets no speed and black to white, as Turbulent Noise draws it (D-445).
fn noise(type_id: &str, p: J) -> String {
    let mut all = json!({"fractal_type": "basic", "noise_type": "smooth", "invert": "off", "size": 100,
        "scale_width": 100, "scale_height": 100, "offset": [0, 0], "complexity": 6, "contrast": 100, "brightness": 0,
        "evolution": 30, "seed": 7, "opacity": 100, "blend": "normal"});
    for (k, v) in p.as_object().unwrap() {
        all[k] = v.clone();
    }
    if type_id == "core.fractal_noise" {
        for (k, v) in [("speed", json!(0)), ("dark_color", json!("#000000")), ("light_color", json!("#ffffff"))] {
            all[k] = v;
        }
    }
    shot(type_id, all)
}

/// Row 4's first channel, linear.
fn row(project: &str) -> Vec<f32> {
    let loaded = persist::load_str(project).expect("the shot reads");
    let mut log = FrameLog::new(8);
    let f = render_frame(loaded.document.project(), &Id::new(MAIN), 0, std::path::Path::new("."), 64, &mut log)
        .expect("the shot draws");
    (0..WIDE).map(|x| f.pixel(x, 4)[0]).collect()
}

/// The widths of the runs of one grey along row 4, the first and last (cut by the edges) left out.
fn cells(project: &str) -> Vec<usize> {
    let row = row(project);
    let mut runs = vec![1usize];
    for x in 1..WIDE {
        if row[x] == row[x - 1] {
            *runs.last_mut().unwrap() += 1;
        } else {
            runs.push(1);
        }
    }
    runs[1..runs.len() - 1].to_vec()
}

/// The display grey's spread: the standard deviation of row 4 encoded to sRGB, in levels of 255.
fn spread(project: &str) -> f64 {
    let enc = |v: f32| {
        let v = v as f64;
        255.0 * if v <= 0.0031308 { 12.92 * v } else { 1.055 * v.powf(1.0 / 2.4) - 0.055 }
    };
    let g: Vec<f64> = row(project).into_iter().map(enc).collect();
    let m = g.iter().sum::<f64>() / g.len() as f64;
    (g.iter().map(|v| (v - m) * (v - m)).sum::<f64>() / g.len() as f64).sqrt()
}

fn largest(a: &[f32], b: &[f32]) -> f32 {
    a.iter().zip(b).map(|(x, y)| (x - y).abs()).fold(0.0, f32::max)
}

#[test]
fn b652_turbulent_size_contrast() {
    let mut t = Table::new(
        "turbulent_noise",
        "# B-652: Turbulent Noise's cell and contrast match After Effects' (D-772)\n\n\
         Seven tutorials from seven creators read our Turbulent Noise 1.36 to 1.51 times too coarse \
         and its greys 0.49 to 0.69 as spread in After Effects. Turbulent Noise now works its noise at \
         c = size / 1.5, Fractal Noise's cell (D-756), so Size 100 at Scale 100 is a 66.7-pixel cell, \
         and its grey is 0.5 + 0.5 n 0.64 contrast / 100 + brightness / 100. The cell widths are counted \
         on a 400-pixel-wide Block noise of one octave; the spreads on a smooth noise of 6 octaves; the \
         fixtures' numbers are the reference's, regenerated by D-772.\n",
    );

    t.heading("The cell, counted in pixels along a row of Block noise of one octave");
    let block = |size: f64| noise("core.turbulent_noise", json!({"noise_type": "block", "complexity": 1, "contrast": 50, "size": size}));
    for (size, lo, hi) in [(100.0, 66, 67), (150.0, 100, 100), (30.0, 20, 20)] {
        let runs = cells(&block(size));
        let ok = !runs.is_empty() && runs.iter().all(|w| (lo..=hi).contains(w));
        let want = if lo == hi { format!("{lo}") } else { format!("{lo} or {hi}") };
        t.row(
            &format!("Turbulent Noise at size {size}: every whole cell is {want} pixels wide (it was {size} before D-772)"),
            &format!("{runs:?}"),
            ok,
        );
    }

    t.heading("The contrast: Turbulent Noise at Contrast C is Fractal Noise at Contrast 0.64 C, the same size");
    for (size, c) in [(100.0, 100.0), (30.0, 100.0), (30.0, 250.0), (30.0, 156.25)] {
        let tn = row(&noise("core.turbulent_noise", json!({"size": size, "contrast": c})));
        let fnz = row(&noise("core.fractal_noise", json!({"size": size, "contrast": c * 0.64})));
        let d = largest(&tn, &fnz);
        t.row(
            &format!("size {size}, Turbulent Noise Contrast {c} against Fractal Noise Contrast {}: every pixel the same", c * 0.64),
            &format!("largest difference {d:.1e}"),
            d <= 1e-6,
        );
    }
    let now = spread(&noise("core.turbulent_noise", json!({"size": 45})));
    let before = spread(&noise("core.fractal_noise", json!({"size": 45, "contrast": 100})));
    let ratio = now / before;
    t.row(
        "Contrast 100 on the same 30-pixel cell: the display greys spread 0.64 times as far as before D-772 (the old rule is Fractal Noise at Contrast 100), within 0.02",
        &format!("spread {now:.2} against {before:.2} levels, {ratio:.3} times"),
        (ratio - 0.64).abs() <= 0.02,
    );
    let old_look = row(&noise("core.turbulent_noise", json!({"size": 45, "contrast": 156.25})));
    let was = row(&noise("core.fractal_noise", json!({"size": 45, "contrast": 100})));
    let d = largest(&old_look, &was);
    t.row(
        "the old look comes back with Size times 1.5 and Contrast times 1.5625: Turbulent Noise at size 45, Contrast 156.25 is what size 30, Contrast 100 drew before",
        &format!("largest difference {d:.1e} against the old rule"),
        d <= 1e-6,
    );

    t.heading("The fixtures, at the reference's new numbers (tolerance 2e-5)");
    t.fixtures("expected_turbulent_noise.json");
    t.fixtures("expected_turbulent_more.json");
    t.fixtures("expected_turbulent_blends.json");

    t.heading("An old project");
    let file = repo("Fixtures/turbulent_noise/fx_turbnoise_001.json");
    let old = persist::load(&file).expect("fx_turbnoise_001.json opens");
    let on_open: Vec<String> = old.warnings.iter().map(|d| d.id.as_str().to_string()).collect();
    t.row(
        "fx_turbnoise_001.json, saved before D-772, opens with no warning",
        &format!("{on_open:?}"),
        on_open.is_empty(),
    );
    let written: J = serde_json::from_str(&fs::read_to_string(&file).unwrap()).unwrap();
    let same = effect_table::same_json(&effect_table::saved(&old), &written);
    t.row(
        "and saves back holding what it held: its size is still 100 and its contrast 100, nothing added",
        if same { "the same" } else { "differs" },
        same,
    );
    let mut log = FrameLog::new(8);
    let _ = render_frame(old.document.project(), &Id::new(MAIN), 4, &t.root, 64, &mut log);
    let at_frame: Vec<String> = log.finish().iter().map(|d| d.id.as_str().to_string()).collect();
    t.row(
        "and draws frame 4 with no warning: the finer cell and flatter greys are the rule, not a fallback",
        &format!("{at_frame:?}"),
        at_frame.is_empty(),
    );

    t.heading("On the card against the processor: within 1 level of 255");
    let mut gpu = Gpu::new().expect("a usable card");
    let mut cases: Vec<(String, anime_compositor::model::Project, std::path::PathBuf)> = Vec::new();
    for (name, project) in [
        ("Block noise at size 100", block(100.0)),
        ("smooth noise at size 30", noise("core.turbulent_noise", json!({"size": 30}))),
        ("turbulent type at size 30, Contrast 250", noise("core.turbulent_noise", json!({"size": 30, "fractal_type": "turbulent", "contrast": 250}))),
    ] {
        let p = persist::load_str(&project).unwrap().document.project().clone();
        cases.push((name.to_string(), p, std::path::PathBuf::from(".")));
    }
    for n in [1u32, 2, 9, 16, 33, 63] {
        let name = format!("fx_turbnoise_{n:03}.json");
        let p = t.load(&name).document.project().clone();
        cases.push((name, p, t.root.clone()));
    }
    for (name, project, root) in &cases {
        let (mut largest, mut refused, mut agree) = (0, false, true);
        for quality in [PreviewQuality::Full, PreviewQuality::Draft] {
            let (d, r, a, b) = both(&mut gpu, project, &Id::new(MAIN), root, 0, quality);
            largest = largest.max(d.0);
            refused |= r;
            agree &= a == b;
        }
        t.row(
            &format!("{name}, frame 0 at Full and Draft"),
            &format!("largest difference {largest} of 255; refused by the card: {refused}; the same warnings: {agree}"),
            largest <= 1 && !refused && agree,
        );
    }

    t.finish("B-652_turbulent_size_contrast_table.md");
}
